import { LitElement, html, TemplateResult } from 'lit';
import { customElement, property, query, state } from 'lit/decorators.js';
import { Option } from '../autocomplete/autocomplete-universal.component.js';
import { ColegiadoApreciador } from '../../model/colegiado-apreciador.model.js';
import { RefProposicaoEmendada } from '../../model/ref-proposicao-emendada.model.js';
import { Comissao } from './comissao.model.js';
import { autoriaCss } from '../../assets/css/autoria.css.js';
import '@awesome.me/webawesome/dist/components/radio/radio.js';
import '@awesome.me/webawesome/dist/components/radio-group/radio-group.js';
import { Destino } from './destino.model.js';

/**
 * Exemplo de uso do componente <lexml-destino>:
 *
 * Caso o projeto utilize Redux para gerenciar alertas globais, você pode integrar
 * o componente passando callbacks via propriedades:
 *
 * ```html
 * <!-- Exemplo de integração com Redux -->
 * <lexml-ui-destino
 *   .addAlert=${a => rootStore.dispatch(adicionarAlerta(a))}
 *   .removeAlert=${id => rootStore.dispatch(removerAlerta(id))}
 *   criticalType=${TipoMensagem.CRITICAL}
 *   .comissoes=${listaDeComissoes}
 *   .proposicao=${proposicao}
 *   .colegiadoApreciador=${colegiado}
 * ></lexml-ui-destino>
 * ```
 *
 * Caso não injete as funções `addAlert` e `removeAlert`, o componente emitirá
 * eventos customizados (`alert:add` e `alert:remove`) que podem ser ouvidos externamente.
 */

export type DestinoAlert = {
  id: string;
  tipo: string; // ex.: 'CRITICAL' | 'WARNING' | 'INFO'
  mensagem: string;
  podeFechar?: boolean;
};

type AddAlertFn = (alerta: DestinoAlert) => void;
type RemoveAlertFn = (id: string) => void;

@customElement('lexml-ui-destino')
export class DestinoComponent extends LitElement {
  @query('#auto-complete') private _autocomplete!: any;

  @state()
  private _comissoesAutocomplete: Option[] = [];

  private _comissaoSelecionada: Comissao | null | undefined = null;

  private isMPV = false;

  private isPlenario = false;

  private tipoColegiadoPlenario = false;

  public isMateriaOrcamentaria = false;

  @state()
  private isErroComissaoSelecionada = false;

  private _proposicao!: RefProposicaoEmendada;

  static styles = [autoriaCss];

  @property({ attribute: false }) addAlert?: AddAlertFn;

  @property({ attribute: false }) removeAlert?: RemoveAlertFn;

  @property({ type: String }) criticalType: string = 'CRITICAL';

  @property({ type: RefProposicaoEmendada })
  set proposicao(value: RefProposicaoEmendada) {
    this._proposicao = value;
    this.isMPV = false;
    if (this._proposicao.sigla === 'MPV') {
      this.isMPV = true;
      this._colegiadoApreciador.tipoColegiado = 'Comissão';
      if (this.isMateriaOrcamentaria) {
        this._colegiadoApreciador.siglaComissao = 'CMO';
        this._autocomplete.value = `${this._colegiadoApreciador.siglaComissao} - COMISSÃO MISTA DE PLANOS, ORÇAMENTOS PÚBLICOS E FISCALIZAÇÃO`;
      } else {
        this._colegiadoApreciador.siglaComissao = `CMMPV ${this._proposicao.numero}/${this._proposicao.ano}`;
        this._autocomplete.value = `${this._colegiadoApreciador.siglaComissao} - COMISSÃO MISTA DA MEDIDA PROVISÓRIA N° ${this._proposicao.numero}, DE ${this._proposicao.ano}`;
      }
    }

    this.requestUpdate();
  }

  constructor() {
    super();
    this._colegiadoApreciador = new ColegiadoApreciador();
    this._colegiadoApreciador.tipoColegiado = 'Plenário';
    this.tipoColegiadoPlenario = true;
  }

  public getDestino(): Destino {
    const d = new Destino();
    d.colegiadoApreciador =
      this._colegiadoApreciador?.tipoColegiado ?? 'Plenário';
    if (d.colegiadoApreciador !== 'Plenário' && this._comissaoSelecionada) {
      d.comissao = { ...this._comissaoSelecionada };
    } else {
      d.comissao = null;
    }
    return d;
  }

  get proposicao(): RefProposicaoEmendada {
    return this._proposicao;
  }

  private _comissoes: Comissao[] = [];
  @property({ type: Array, state: true })
  set comissoes(value: Comissao[]) {
    this.isPlenario = false;
    if (!this._comissoes || this._comissoes.length === 0) {
      this._comissoes = value ? value : [];
      this._comissoesOptions = this.comissoes.map(
        comissao =>
          new Option(comissao.sigla, `${comissao.sigla} - ${comissao.nome}`),
      );
      this.ajustarValorAutocomplete();
      this.requestUpdate();
    }
    if (typeof value === 'undefined') {
      this.isPlenario = true;
    }
  }

  get comissoes(): Comissao[] {
    return this._comissoes;
  }

  private _comissoesOptions: Option[] = [];

  private ajustarValorAutocomplete(): void {
    if (this._colegiadoApreciador?.siglaComissao) {
      const option: Option =
        this._comissoesOptions.find(
          op => op.value === this._colegiadoApreciador.siglaComissao,
        ) || new Option('', '');
      this._selecionarComissao(option);
      this._autocomplete.value =
        option.description || this._colegiadoApreciador.siglaComissao;
    }
  }

  private _colegiadoApreciador!: ColegiadoApreciador;
  @property({ type: Object, state: true })
  set colegiadoApreciador(value: ColegiadoApreciador | undefined) {
    this._colegiadoApreciador = value ? value : new ColegiadoApreciador();
    this.tipoColegiadoPlenario =
      this._colegiadoApreciador.tipoColegiado === 'Plenário';
    if (this.tipoColegiadoPlenario) {
      this.ajustarTipoColegiadoPlenario();
    } else if (this._colegiadoApreciador.siglaComissao) {
      this.ajustarValorAutocomplete();
    } else {
      this._autocomplete.value = '';
    }
    if (
      !this.tipoColegiadoPlenario &&
      !this._colegiadoApreciador.siglaComissao
    ) {
      this.criarAlertaErroComissao();
    }
    this.requestUpdate();
  }

  public get colegiadoApreciador(): ColegiadoApreciador {
    return this._colegiadoApreciador;
  }

  render(): TemplateResult {
    return html`
      <style>
        fieldset {
          font-size: 14px;
          font-family: 'Helvetica Neue', 'Helvetica', 'Arial', sans-serif;
          display: flex;
          flex-direction: column;
          gap: 1em;
          background-color: var(--wa-color-gray-95);
          box-shadow: var(--wa-shadow-m);
          flex-wrap: wrap;
          padding: 20px 20px;
          border: solid var(--wa-panel-border-width) var(--wa-color-gray-90);
          border-radius: var(--wa-border-radius-s);
          max-width: 655px;
        }

        legend {
          background-color: var(--wa-color-gray-90);
          font-weight: bold;
          border-radius: 5px;
          border: 1px solid var(--wa-color-gray-85);
          padding: 2px 5px;
          box-shadow: var(--wa-shadow-s);
          color: #333;
        }

        .mensagem {
          font-size: 0.8em;
          font-weight: normal;
          text-align: left;
          border: 1px solid;
          padding: 4px 10px;
          margin: 10px 0;
          display: inline-block;
          border-radius: 2px;
          font-family: var(--wa-font-sans);
        }

        .mensagem--danger {
          color: #721c24;
          background-color: #f8d7da;
          border-color: #f5c6cb;
        }
        wa-radio {
          font-size: 14px;
        }
      </style>
      <fieldset class="lexml-destino">
        <legend>Destino</legend>
        <div>
          <wa-radio-group
            id="tipoColegiado"
            .value=${this._colegiadoApreciador?.tipoColegiado}
          >
            <wa-radio
              name="tipoColegiado"
              @click=${(): void => this.updateTipoColegiado('Plenário')}
              @wa-change=${(evt: any): void =>
                evt.target?.checked && this.updateTipoColegiado('Plenário')}
              ?checked=${this._colegiadoApreciador?.tipoColegiado ===
              'Plenário'}
              value="Plenário"
              ?disabled=${this.isMPV || this.isPlenario}
              >Plenário</wa-radio
            >
            <wa-radio
              name="tipoColegiado"
              @click=${(): void => this.updateTipoColegiado('Comissão')}
              @wa-change=${(evt: any): void =>
                evt.target?.checked && this.updateTipoColegiado('Comissão')}
              ?checked=${this._colegiadoApreciador?.tipoColegiado ===
              'Comissão'}
              value="Comissão"
              ?disabled=${this.isMPV || this.isPlenario}
              >Comissão</wa-radio
            >

            <wa-radio
              name="tipoColegiado"
              @click=${(): void =>
                this.updateTipoColegiado('Plenário via Comissão')}
              @wa-change=${(evt: any): void =>
                evt.target?.checked &&
                this.updateTipoColegiado('Plenário via Comissão')}
              ?checked=${this._colegiadoApreciador?.tipoColegiado ===
              'Plenário via Comissão'}
              value="Plenário via Comissão"
              ?disabled=${this.isMPV || this.isPlenario}
              >Plenário via Comissão</wa-radio
            >
          </wa-radio-group>
        </div>
        <div style="width:100%;margin-top:10px">
          <lexml-autocomplete-universal
            id="auto-complete"
            label="Comissão"
            .mode=${'sync'}
            ?readonly=${this.isMPV || this.isPlenario}
            placeholder="ex: Comissão"
            .items=${this._comissoesOptions}
            .onSelect=${(opt: Option): void => this._selecionarComissao(opt)}
            .onClick=${(): string => (this._autocomplete.value = '')}
            @blur=${this._blurAutoComplete}
            ?disabled=${this.isMPV ||
            this.isPlenario ||
            this.tipoColegiadoPlenario ||
            !this.comissoes?.length}
          ></lexml-autocomplete-universal>
          ${this.isErroComissaoSelecionada
            ? html`
                <div class="mensagem mensagem--danger">
                  A comissão de destino deve ser selecionada.
                </div>
              `
            : ''}
        </div>
      </fieldset>
    `;
  }

  private _exibirComissoes(): void {
    this._autocomplete.value = '';
    this._comissoesAutocomplete = [];
  }

  private criarAlertaErroComissao(): void {
    this.isErroComissaoSelecionada = true;

    const alerta: DestinoAlert = {
      id: 'alerta-global-comissao-nao-selecionada',
      tipo: this.criticalType,
      mensagem: 'A comissão de destino deve ser selecionada.',
      podeFechar: false,
    };

    if (this.addAlert) {
      this.addAlert(alerta);
    } else {
      this.dispatchEvent(
        new CustomEvent<DestinoAlert>('alert:add', {
          bubbles: true,
          composed: true,
          detail: alerta,
        }),
      );
    }
  }

  private removerAlertaErroComissao(): void {
    this.isErroComissaoSelecionada = false;
    const id = 'alerta-global-comissao-nao-selecionada';

    if (this.removeAlert) {
      this.removeAlert(id);
    } else {
      this.dispatchEvent(
        new CustomEvent('alert:remove', {
          bubbles: true,
          composed: true,
          detail: { id },
        }),
      );
    }
  }

  private updateTipoColegiado(value: any): void {
    if (!this.isMPV && !this.isPlenario) {
      this._colegiadoApreciador.tipoColegiado = value;
      this.tipoColegiadoPlenario =
        this._colegiadoApreciador.tipoColegiado === 'Plenário';
      if (this.tipoColegiadoPlenario) this.ajustarTipoColegiadoPlenario();
      this.requestUpdate();
    }
  }

  private _selecionarComissao(item?: Option): void {
    if (!item?.value) return;

    if (!this._colegiadoApreciador) {
      this._colegiadoApreciador = new ColegiadoApreciador();
    }
    this._comissaoSelecionada = null;
    this._comissaoSelecionada = this._comissoes.find(
      op => op.sigla === item.value,
    );
    if (!this._comissaoSelecionada) return;

    this._colegiadoApreciador.siglaCasaLegislativa =
      this._comissaoSelecionada.siglaCasaLegislativa;
    this._colegiadoApreciador.siglaComissao = this._comissaoSelecionada.sigla;

    this.removerAlertaErroComissao();
  }

  private _blurAutoComplete(): void {
    if (!this.comissoes?.length) return;

    setTimeout(() => {
      const comissao = this._autocomplete.value ?? '';
      const comissaoSelecionada = this._comissoesOptions.find(
        comissaoOp => comissao === comissaoOp.description,
      );

      if (!comissaoSelecionada) {
        this._colegiadoApreciador.siglaComissao = '';
        this.criarAlertaErroComissao();
        this._autocomplete.value = '';
      }
    }, 200);
  }

  private emitirEventoOnChange(origemEvento: string): void {
    this.dispatchEvent(
      new CustomEvent('onchange', {
        bubbles: true,
        composed: true,
        detail: {
          origemEvento,
        },
      }),
    );
  }

  private ajustarTipoColegiadoPlenario(): void {
    this._autocomplete.value = '';
    this._colegiadoApreciador.siglaComissao = '';
    this.removerAlertaErroComissao();
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'lexml-ui-destino': DestinoComponent;
  }
}
