import { LitElement, html, TemplateResult, PropertyValues } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import '@awesome.me/webawesome/dist/components/callout/callout.js';
import '@awesome.me/webawesome/dist/components/button/button.js';
import '@awesome.me/webawesome/dist/components/icon/icon.js';
import '@awesome.me/webawesome/dist/components/badge/badge.js';
import { Alerta } from '../../model/alerta/alerta.model';
import { TipoMensagem } from '../../utils/mensagem';

/**
 * Exemplo de uso do componente <lexml-ui-alertas>:
 *
 * Caso o projeto utilize Redux para gerenciar alertas, injete callbacks pelo PAI:
 *
 * ```html
 * <lexml-ui-alertas
 *   .alertas=${store.getState().elementoReducer.ui?.alertas ?? []}
 *   .removeAlert=${(id: string) => store.dispatch(removerAlerta(id))}
 *   .clearAlerts=${() => store.dispatch(limparAlertas())}
 *   .seletorHost=${'lexml-emenda'}              <!-- opcional -->
 *   .seletorBadge=${'#contadorAvisos wa-badge'}  <!-- opcional -->
 *   @alertas:alterados=${(e: CustomEvent<{ total: number; aumentou: boolean }>) => {
 *     // opcional: usar e.detail.total / e.detail.aumentou
 *   }}
 * ></lexml-ui-alertas>
 * ```
 *
 * Caso NÃO injete `removeAlert`/`clearAlerts`, o componente emitirá eventos
 * (`alert:remove` com { id } e `alert:clear`) que podem ser ouvidos externamente:
 *
 * ```html
 * <lexml-ui-alertas
 *   .alertas=${meusAlertas}
 *   @alert:remove=${(e: CustomEvent<{ id: string }>) => store.dispatch(removerAlerta(e.detail.id))}
 *   @alert:clear=${() => store.dispatch(limparAlertas())}
 * ></lexml-ui-alertas>
 * ```
 */

type RemoveAlertFn = (id: string) => void;
type ClearAlertsFn = () => void;

const mapTipoMensagem: Record<
  TipoMensagem,
  {
    icon: string;
    variant: 'brand' | 'warning' | 'danger' | 'success' | 'neutral';
  }
> = {
  [TipoMensagem.INFO]: { icon: 'circle-info', variant: 'brand' },
  [TipoMensagem.WARNING]: { icon: 'triangle-exclamation', variant: 'warning' },
  [TipoMensagem.ERROR]: { icon: 'circle-exclamation', variant: 'danger' },
  [TipoMensagem.CRITICAL]: { icon: 'circle-exclamation', variant: 'danger' },
  [TipoMensagem.SUCCESS]: { icon: 'circle-check', variant: 'success' },
};

@customElement('lexml-ui-alertas')
export class AlertasComponent extends LitElement {
  @property({ type: Array }) alertas: Alerta[] = [];

  @property({ attribute: false }) removeAlert?: RemoveAlertFn;
  @property({ attribute: false }) clearAlerts?: ClearAlertsFn;

  @property({ type: String }) seletorHost: string = 'lexml-emenda';
  @property({ type: String }) seletorBadge: string = '#contadorAvisos wa-badge';

  stateChanged(state: any): void {
    this.alertas = state.elementoReducer.ui?.alertas || [];
  }

  private _lastCount = 0;

  getAlertIcon(tipoAlerta: TipoMensagem): TemplateResult {
    return html`<wa-icon
      slot="icon"
      name="${mapTipoMensagem[tipoAlerta].icon}"
    ></wa-icon>`;
  }

  limparAlertas(): void {
    if (this.clearAlerts) {
      this.clearAlerts();
    } else {
      this.dispatchEvent(
        new CustomEvent('alert:clear', {
          bubbles: true,
          composed: true,
        }),
      );
    }
  }

  removeAlertaById(id: string): void {
    if (this.removeAlert) {
      this.removeAlert(id);
    } else {
      this.dispatchEvent(
        new CustomEvent('alert:remove', {
          bubbles: true,
          composed: true,
          detail: { id },
        }),
      );
    }
  }

  private onCloseClick = (e: Event): void => {
    e.stopPropagation();
    (e as any).stopImmediatePropagation?.();
    const id = (e.currentTarget as HTMLElement)?.dataset?.id;
    if (id) this.removeAlertaById(id);
  };

  updated(changedProperties: PropertyValues): void {
    if (changedProperties.has('alertas')) {
      this.alertas?.forEach(alerta => {
        this.shadowRoot
          ?.getElementById(alerta.id)
          ?.addEventListener('click', (event: any) => {
            event.stopImmediatePropagation();
            this.removeAlertaById((event.target as Element).id);
          });
      });
      const host: any = this.seletorHost
        ? document.querySelector(this.seletorHost)
        : null;

      if (host) {
        host.totalAlertas = this.alertas.length;
      }

      const oldValue = changedProperties.get('alertas')?.length || 0;
      const newValue = this.alertas.length;

      if (host && newValue > oldValue) {
        const badge = this.seletorBadge
          ? (document.querySelector(this.seletorBadge) as HTMLElement | null)
          : null;

        if (badge) {
          badge.setAttribute('attention', 'none');
          void (badge as any).offsetWidth;
          badge.setAttribute('attention', 'pulse');
        }
      }
      this.dispatchEvent(
        new CustomEvent('alertas:alterados', {
          bubbles: true,
          composed: true,
          detail: { total: newValue, aumentou: newValue > oldValue },
        }),
      );
    }
  }

  render(): TemplateResult {
    return html`
      <style>
        wa-callout {
          box-shadow: var(--wa-shadow-l);
          margin: 20px;
        }
        .field__alert {
          display: flex;
          align-items: center;
          justify-content: space-between;
        }
        .alert__close-button {
          cursor: pointer;
        }
        wa-button::part(base) {
          background-color: transparent;
        }
      </style>
      ${this.alertas.map(
        alerta =>
          html` ${alerta.podeFechar
            ? html`
                <wa-callout
                  variant="${mapTipoMensagem[alerta.tipo].variant}"
                  appearance="outlined filled"
                >
                  ${this.getAlertIcon(alerta.tipo)}
                  <div class="field__alert">
                    ${alerta.mensagem}
                    <wa-button
                      appearance="plain"
                      size="small"
                      class="alert__close-button"
                      data-id="${alerta.id}"
                      aria-label="fechar"
                      @click=${this.onCloseClick}
                    >
                      <wa-icon
                        class="icon__close"
                        name="xmark"
                        label="Fechar"
                      ></wa-icon>
                    </wa-button>
                  </div>
                </wa-callout>
              `
            : html`<wa-callout
                variant="${mapTipoMensagem[alerta.tipo].variant}"
                appearance="outlined"
              >
                ${this.getAlertIcon(alerta.tipo)}${alerta.mensagem}
              </wa-callout> `}`,
      )}
    `;
  }
}
